WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_data_rank_comprehensive'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '综合排序', 'kp-xingce-data-rank-comprehensive', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "综合排序"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "不同维度、毫无关联的三个指标混合排序。核心战法：挑软柿子捏。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "最耗时的题型：“2023年①利润率、②出口增速、③进口增量占贸易总额比重，由大到小排序正确的是？”。这是三道独立的计算题揉在了一起。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、战术法则"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "1. 挑软柿子捏：", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 三个指标，必然有一个数据特别好找、算式特别简单（比如直接在图上读个数，或者分母只有一位数）。"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "2. 选项定位验证：", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 算出一个极易算的指标作为基准锚点，然后通过估算判断另外两个指标比这个基准大还是小。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[列出题目要求的三个独立指标式子] --> B[扫描三个式子, 找出一个最不需要列笔算、能一眼估算出来的]\nB --> C[算出这个'软柿子'的值 (如算出来是 15%)]\nC --> D[去估算另外两个硬骨头式子]\nD --> E{它们和 15% 怎么比?}\nE -- 明显大于15% --> F[排在软柿子前面]\nE -- 明显小于15% --> G[排在软柿子后面]\nF --> H[结合选项直接秒杀出唯一答案]\nG --> H"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 排大小：①A比重(200/1000)；②B增速(300比上年增20)；③C比重(8980/30000)。选项：A. ①>③>② B. ③>①>②"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "找软柿子：①式子 200/1000 简直就是送分的，一眼看出来是 20%。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "作为锚点：把 20% 作为试金石。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "看 ②：300是现期，增20。基期量 = 280。增速 = 20 / 280 ≈ 1/14 ≈ 7.1%。明显远小于 20%。所以 ① > ②。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "看 ③：8980 / 30000。分母是3，分子不到9，显然商不到 30%。但因为 30000 的 20% 是 6000，而分子 8980 > 6000，说明 ③ 明显大于 20%！"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "定序：③(>20%) > ①(=20%) > ②(<20%)。选 B。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "顺序计算强迫症：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "从 ① 算到 ③ 是死路一条。如果 ① 的式子极其复杂（比如 4567/8912），你上来就死磕 ①，可能 3 分钟就没了，而实际上只要先算出了好算的 ③（比如10%），用10%去试 ①，一眼就能看出它大于10%。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "练就一套“找基准值”的法眼。在综合排序里，谁最好算，谁就是那把丈量整个题目的尺子。"}]}]}$$ AS jsonb), NULL, '综合排序的核心考点与实战推导。', category_node.id, CAST('["资料分析", "综合排序"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_rank_comprehensive", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
